/**
 * @fileoverview Generates the utilities layer from `src/base/utilities.ts`.
 * Pure functions take explicit inputs and return CSS text so
 * tests can pin literals; `main()` writes the files into `src/base/`.
 *
 * Usage: `vp run generate` (or `node scripts/generate-utilities.ts`). The
 * generated files are committed; `generate-utilities.test.ts` fails when they
 * are stale.
 */

import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  BOX_SHADOW_COMPOSITE,
  SHORTHAND_OF,
  BORDER_SIDES,
  type Breakpoint,
  BREAKPOINT_REM,
  BREAKPOINTS,
  DISPLAY_SHORTHANDS,
  type Family,
  GRADIENT_TYPES,
  hasGroup,
  isState,
  type Utility,
  UTILITIES,
  PSEUDO_ONLY,
  PSEUDO_SIDES,
  type PseudoSide,
  STUCK_STATE,
  STATE_SELECTORS,
  STATES,
  tiersOf,
} from "../src/base/utilities.ts";

const BANNER =
  "/* Generated by scripts/generate-utilities.ts from src/base/utilities.ts — do not edit. */\n";

function register(name: string, syntax = '"*"', initial?: string, inherits = false): string {
  const init = initial === undefined ? "" : ` initial-value: ${initial};`;
  return `@property --${name} { syntax: ${syntax}; inherits: ${inherits};${init} }\n`;
}

/**
 * The query a breakpoint tier sits in: the nearest ancestor inline-size
 * container, in rem (the same in any font). html is the page container, each
 * child of a layout is one, and `data-ui="container"` makes any element one.
 */
export function breakpointQuery(bp: Breakpoint): string {
  return `@container (width >= ${BREAKPOINT_REM[bp]}rem)`;
}

/** A utility's base registrations: the utility, its base layer variable, its resolver, and the dual pair. */
export function registrations(utility: Utility): string {
  const n = utility.name;
  let out = register(n) + register(`_${n}`) + register(`_${n}-resolved`);
  if (utility.mode === "dual") {
    out += register(`_${n}-len`, '"<length-percentage>"', "0px");
    out += register(`_${n}-num`, '"<number>"', "0");
  }
  if (utility.emit === "px") {
    out += register(`_${n}-len`, '"<length>"', "0px");
    out += register(`_${n}-num`, '"<number>"', "0");
    out += register(`_${n}-w`);
  }
  if (utility.emit === "border") {
    out += register(`_${n}-len`, '"<length>"', "0px");
    out += register(`_${n}-num`, '"<number>"', "0");
    out += register(`_${n}-is-len`, '"<number>"', "0");
    out += register(`_${n}-is-num`, '"<number>"', "0");
    out += register(`_${n}-clr`, '"<color>"', "transparent");
    const inherits = utility.inherits === true;
    out += register(`_${n}-w`, undefined, undefined, inherits);
    out += register(`_${n}-c`, undefined, undefined, inherits);
  }
  return out;
}

/** One tier of a utility: the modifier utility and its layer variable; states add the group twin. */
export function tierRegistrations(utility: Utility, tier: string): string {
  let out = register(`${utility.name}--${tier}`) + register(`_${utility.name}-${tier}`);
  if (isState(tier) && hasGroup(tier)) {
    out += register(`group-${utility.name}--${tier}`) + register(`_${utility.name}-g-${tier}`);
  }
  return out;
}

/** The precedence chain over a utility's layer variables: `tiers` highest-precedence first, ending in `end`. */
export function chain(name: string, tiers: readonly string[], end: string): string {
  return tiers.reduceRight((inner, tier) => `var(--_${name}-${tier}, ${inner})`, end);
}

/**
 * The resolver and the base rule for one utility. State tiers chain the starting
 * state, own states, group states, then the scroll state.
 */
export function baseRule(utility: Utility, tiers: readonly string[]): string {
  const n = utility.name;
  const stateTiers = tiers.some(isState);
  // Precedence: the starting state (highest: it only exists in the starting style),
  // own pseudo states, their group forms, the stuck state, then breakpoints descending
  // (a state beats a breakpoint, as in Tailwind), then the base.
  const pseudoStates = tiers.filter((tier) => isState(tier) && hasGroup(tier));
  const flagged = (flag: "starting" | "stuck") =>
    tiers.filter((tier) => isState(tier) && STATE_SELECTORS[tier][flag]);
  const breakpoints = tiers.filter((tier) => !isState(tier)).reverse();
  const chainTiers = stateTiers
    ? [
        ...flagged("starting"),
        ...pseudoStates,
        ...pseudoStates.map((tier) => `g-${tier}`),
        ...flagged("stuck"),
        ...breakpoints,
      ]
    : breakpoints;
  const gates = [`[style*="--${n}:"]`, `[style*="--${n}--"]`];
  if (stateTiers) gates.push(`[style*="--group-${n}--"]`);
  const end = utility.chainEnd ? `var(--_${n}, ${utility.chainEnd})` : `var(--_${n})`;
  const lines = [
    `:where(${gates.join(", ")}) {`,
    `  --_${n}-resolved: ${chain(n, chainTiers, end)};`,
    // a number fails the <length> half and a length the <number> half (each
    // then takes its 0 initial), so one signed length remains
    ...(utility.emit === "px"
      ? [
          `  --_${n}-len: var(--_${n}-resolved);`,
          `  --_${n}-num: var(--_${n}-resolved);`,
          `  --_${n}-w: calc(var(--_${n}-len) + var(--_${n}-num) * 1px);`,
        ]
      : []),
    `}`,
    `:where([style*="--${n}:"]) {`,
    `  --_${n}: var(--${n});`,
  ];
  if (utility.emit === "border") {
    lines.push(...borderChannels(n).map((d) => `  ${d}`));
  } else if (utility.mode === "dual") {
    lines.push(`  --_${n}-len: var(--_${n}-resolved);`, `  --_${n}-num: var(--_${n}-resolved);`);
    for (const property of utility.properties) {
      lines.push(`  ${property}: calc(var(--_${n}-len) + var(--_${n}-num) * var(--spacing));`);
    }
  } else {
    const extra = companions(utility);
    lines.push(...extra.before.map((d) => `  ${d}`));
    for (const property of utility.properties) {
      lines.push(`  ${property}: ${emission(utility, `var(--_${n}-resolved)`)};`);
    }
    lines.push(...extra.after.map((d) => `  ${d}`));
  }
  lines.push(`}`, ``);
  return lines.join("\n");
}

/**
 * Keyword rules for a utility with keywords (until CSS `if()` can branch per
 * value). The typed rule above cannot carry a keyword, so: one rule emits a
 * base keyword as written; then, per breakpoint in ascending order inside its
 * flag query, a restore rule re-emits the typed value when that tier is set and
 * a keyword rule emits it as written when that tier holds a keyword. Same
 * (zero) specificity and later in source, so the highest active tier wins and
 * numbers and keywords mix freely across tiers (`--w: 4; --w--md: auto`).
 */
export function keywordRules(
  utility: Utility,
  tiers: readonly string[],
  defaults?: { skips: readonly string[] },
): string {
  const n = utility.name;
  const keywords = utility.keywords ?? [];
  if (keywords.length === 0) return "";
  if (tiers.some(isState)) throw new Error(`--${n}: keywords need a breakpoint family`);
  if (defaults && utility.noBase === undefined) return "";
  const forms = (tier: string) =>
    `:is(${keywords.map((keyword) => `[style*="--${n}${tier ? `--${tier}` : ""}: ${keyword}"]`).join(", ")})`;
  // a tier applies where its rule does: with a base, or (in the defaults layer, the
  // no-base rule's copy) anywhere the no-base rule is not skipped
  const applies = defaults
    ? defaults.skips.length
      ? `:not(${defaults.skips.join(", ")})`
      : ""
    : `[style*="--${n}:"]`;
  const raw = utility.properties.map((property) => `  ${property}: var(--_${n}-resolved);`);
  const typed = utility.properties.map((property) =>
    utility.mode === "dual"
      ? `  ${property}: calc(var(--_${n}-len) + var(--_${n}-num) * var(--spacing));`
      : `  ${property}: ${emission(utility, `var(--_${n}-resolved)`)};`,
  );
  const lines = defaults ? [] : [`:where(${forms("")}) {`, ...raw, `}`];
  for (const tier of tiers) {
    lines.push(
      `${breakpointQuery(tier as Breakpoint)} {`,
      `  :where(${applies}[style*="--${n}--${tier}:"]) {`,
      ...typed.map((line) => `  ${line}`),
      `  }`,
      `  :where(${applies}${forms(tier)}) {`,
      ...raw.map((line) => `  ${line}`),
      `  }`,
      `}`,
    );
  }
  lines.push(``);
  return lines.join("\n");
}

/**
 * Keyword shorthands (`utility.aliases`): one exact-value rule per keyword that
 * rewrites the layer variable, at the base and at every tier, each placed where
 * that tier's setter is (a breakpoint's container query, a state's pseudo-class
 * and its group form, `@starting-style`, or behind the stuck switch). The family
 * file loads after the tier setters, so each rule overrides the raw copy.
 */
export function aliasRules(utility: Utility, tiers: readonly string[]): string {
  const n = utility.name;
  const aliases = Object.entries(utility.aliases ?? {});
  if (aliases.length === 0) return "";
  const each = (gate: (keyword: string) => string, layer: string, value = (v: string) => v) =>
    aliases.map(([keyword, v]) => `:where(${gate(keyword)}) { --_${layer}: ${value(v)}; }`);
  const lines = each((k) => `[style*="--${n}: ${k}"]`, n);
  const indent = (body: string[]) => body.map((line) => `  ${line}`);
  for (const tier of tiers) {
    const own = (k: string) => `[style*="--${n}--${tier}: ${k}"]`;
    if (!isState(tier)) {
      lines.push(
        `${breakpointQuery(tier as Breakpoint)} {`,
        ...indent(each(own, `${n}-${tier}`)),
        `}`,
      );
      continue;
    }
    const { pseudo, media, stuck, starting } = STATE_SELECTORS[tier];
    if (starting) {
      lines.push(`@starting-style {`, ...indent(each(own, `${n}-${tier}`)), `}`);
    } else if (stuck) {
      lines.push(...each(own, `${n}-${tier}`, (v) => `var(--_stuck-on) ${v}`));
    } else {
      // the pseudo-class first: it is a flag test, the substring scans the attribute
      const body = [
        ...each((k) => `${pseudo}${own(k)}`, `${n}-${tier}`),
        ...each(
          (k) => `[data-ui~="group"]${pseudo} [style*="--group-${n}--${tier}: ${k}"]`,
          `${n}-g-${tier}`,
        ),
      ];
      lines.push(...(media ? [`@media ${media} {`, ...indent(body), `}`] : body));
    }
  }
  return lines.join("\n") + "\n";
}

/**
 * The `--display` shorthands: `flex-col` and friends set the display and the
 * flex direction together, at the base and at each breakpoint, so a tier that
 * names any display resets the direction to row unless it is a shorthand. The
 * direction resolves through its own channel (`--_flex-direction-*`, what the
 * field primitive reads), emitted only on elements that use a shorthand.
 */
export function displayShorthandRules(): string {
  const entries = Object.entries(DISPLAY_SHORTHANDS);
  const block = (tier: string) => {
    const suffix = tier ? `--${tier}` : "";
    const layer = tier ? `-${tier}` : "";
    return [
      `:where([style*="--display${suffix}:"]) { --_flex-direction${layer}: row; }`,
      ...entries.map(
        ([keyword, [display, direction]]) =>
          `:where([style*="--display${suffix}: ${keyword}"]) { --_display${layer}: ${display}; --_flex-direction${layer}: ${direction}; }`,
      ),
    ];
  };
  const lines = block("");
  for (const bp of BREAKPOINTS) {
    lines.push(`${breakpointQuery(bp)} {`, ...block(bp).map((line) => `  ${line}`), `}`);
  }
  lines.push(
    `:where([style*="flex-row"], [style*="flex-col"]) {`,
    `  --_flex-direction-resolved: ${chain("flex-direction", [...BREAKPOINTS].reverse(), "var(--_flex-direction)")};`,
    `  flex-direction: var(--_flex-direction-resolved);`,
    `}`,
  );
  return lines.join("\n") + "\n";
}

/**
 * The border shorthand's channels. Each typed channel takes the
 * resolved value; one whose syntax the value does not match falls back to its
 * initial value at computed-value time, so exactly one of the flags is 1 for a
 * number or a length, and both are 0 for a color.
 */
function borderChannels(n: string): string[] {
  const resolved = `var(--_${n}-resolved)`;
  const isColor = `(1 - var(--_${n}-is-num) - var(--_${n}-is-len))`;
  return [
    `--_${n}-len: ${resolved};`,
    `--_${n}-num: ${resolved};`,
    `--_${n}-is-len: calc(sin(atan2(${resolved}, 1px)) * 0 + 1);`,
    `--_${n}-is-num: calc(${resolved} * 0 + 1);`,
    `--_${n}-clr: ${resolved};`,
    `--_${n}-w: calc(abs(var(--_${n}-len)) + abs(var(--_${n}-num)) * 1px + ${isColor} * 1px);`,
    `--_${n}-c: color-mix(in oklch, var(--_${n}-clr) calc(${isColor} * 100%), var(--color-border));`,
  ];
}

/**
 * One rule per physical side, gated on any shorthand covering it.
 * Precedence: the all-sides longhand, then the side, axis, and all-sides
 * shorthands. Style defaults to solid unless `--border-style` is set.
 */
export function borderSideRules(): string {
  const out: string[] = [];
  for (const { property, shorthands } of BORDER_SIDES) {
    const fallback = (part: "w" | "c") =>
      shorthands.reduceRight<string>(
        (inner, name) => (inner ? `var(--_${name}-${part}, ${inner})` : `var(--_${name}-${part})`),
        "",
      );
    const longhand = (kind: "width" | "color", part: "w" | "c") =>
      `var(--_border-${kind}-resolved, ${fallback(part)})`;
    out.push(
      `:where(${[...shorthands]
        .reverse()
        .map((name) => `[style*="--${name}:"]`)
        .join(", ")}) {`,
      `  ${property}-width: ${longhand("width", "w")};`,
      `  ${property}-style: var(--_border-style-resolved, solid);`,
      `  ${property}-color: ${longhand("color", "c")};`,
      `}`,
    );
  }
  return out.join("\n") + "\n";
}

/** The value a utility's property is set to, given the resolved value expression. */
function emission(utility: Utility, resolved: string): string {
  if (utility.emit === "repeat") return `repeat(${resolved}, minmax(0, 1fr))`;
  if (utility.emit === "span") return `span ${resolved} / span ${resolved}`;
  if (utility.emit === "grid-fit") return `repeat(auto-fit, minmax(min(${resolved}, 100%), 1fr))`;
  if (utility.emit === "bg")
    return `oklch(from ${resolved} l c h / calc(alpha * var(--_bg-alpha-resolved, 1)))`;
  return resolved;
}

/** Declarations that ride along with a utility's emission (compound utilities). */
function companions(utility: Utility): { before: string[]; after: string[] } {
  if (utility.emit === "line-clamp") {
    return {
      before: ["display: -webkit-box;", "-webkit-box-orient: vertical;"],
      after: ["overflow: hidden;"],
    };
  }
  return { before: [], after: [] };
}

/**
 * The no-base rule for an allowlisted utility, in `@layer defaults`: gated on
 * any tier, the chain ends in the value a plain element shows (`0` padding) as
 * a literal. The layer
 * sits above `reset` (so it beats the reset's universal zeroing) and below
 * every component, vendor, and legacy layer, so any of those that sets the
 * property wins: the element keeps its own value, and a tier alone applies
 * there only where that rule reads the resolver. `skips` are the reset-layer
 * rules that style an element on purpose (inline code's padding, a switch).
 */
export function noBaseRule(utility: Utility, skips: readonly string[] = []): string {
  const n = utility.name;
  // a utility with no tiers has no tier-only form
  if (utility.noBase === undefined || !tiersOf(utility).length) return "";
  const not = skips.length ? `:not(${skips.join(", ")})` : "";
  return [
    `:where(${tierGate(n)}${not}) {`,
    ...emitResolved(utility, `var(--_${n}-resolved, ${utility.noBase})`),
    `}`,
    ``,
  ].join("\n");
}

/** Any tier of `--<n>`, own or group form. */
function tierGate(n: string): string {
  return `:is([style*="--${n}--"], [style*="--group-${n}--"])`;
}

/** A utility's declarations, reading `resolved` (its chain plus a fallback). */
function emitResolved(utility: Utility, resolved: string): string[] {
  const n = utility.name;
  return utility.mode === "dual"
    ? [
        `  --_${n}-len: ${resolved};`,
        `  --_${n}-num: ${resolved};`,
        ...utility.properties.map(
          (property) =>
            `  ${property}: calc(var(--_${n}-len) + var(--_${n}-num) * var(--spacing));`,
        ),
      ]
    : utility.properties.map((property) => `  ${property}: ${emission(utility, resolved)};`);
}

/**
 * A longhand's tier beside its shorthand's base, in `ui.utilities` (the tier
 * alone is in `@layer defaults`, which the shorthand's base would beat). A dual
 * longhand falls back to the shorthand's value below the tier. A raw one
 * (`--basis` under `--flex`) cannot read a part of the shorthand, so it gets one
 * rule per breakpoint, inside that breakpoint's query: below the tier it
 * declares nothing, and the shorthand's part stands.
 */
export function shorthandTierRule(utility: Utility): string {
  const n = utility.name;
  const shorthands = SHORTHAND_OF[n];
  const tiers = tiersOf(utility);
  if (!shorthands || !tiers.length) return "";
  const bases = `:is(${shorthands.map((name) => `[style*="--${name}:"]`).join(", ")})`;
  if (utility.mode === "dual") {
    const fallback = shorthands.reduceRight(
      (inner, name) => `var(--_${name}-resolved, ${inner})`,
      "0",
    );
    return [
      `:where(${bases}${tierGate(n)}) {`,
      ...emitResolved(utility, `var(--_${n}-resolved, ${fallback})`),
      `}`,
      ``,
    ].join("\n");
  }
  if (tiers.some(isState))
    throw new Error(`--${n}: a raw longhand's shorthand tiers need breakpoints`);
  return tiers
    .map((tier) =>
      [
        `${breakpointQuery(tier as Breakpoint)} {`,
        `  :where(${bases}[style*="--${n}--${tier}:"]) {`,
        ...emitResolved(utility, `var(--_${n}-resolved)`).map((line) => `  ${line}`),
        `  }`,
        `}`,
      ].join("\n"),
    )
    .join("\n")
    .concat("\n");
}

/** One tier's setter: gated generically, copies every utility of that tier into its layer variable. */
export function setterRule(tier: string, utilities: readonly Utility[]): string {
  const inTier = utilities.filter((utility) => tiersOf(utility).includes(tier));
  const indent = (lines: string[], depth: number) => lines.map((line) => " ".repeat(depth) + line);
  if (isState(tier) && STATE_SELECTORS[tier].stuck) return stuckSetter(tier, inTier);
  if (isState(tier) && STATE_SELECTORS[tier].starting) {
    // @starting-style applies only in the style an element transitions from (first
    // render, or leaving display: none); the starting layer variable heads every
    // chain, so the utility resolves to --<utility>--starting there and to its
    // usual value after, and a --transition animates between the two.
    const body = [
      `:where([style*="--${tier}:"]) {`,
      ...inTier.map((utility) => `  --_${utility.name}-${tier}: var(--${utility.name}--${tier});`),
      `}`,
    ];
    return [`@starting-style {`, ...indent(body, 2), `}`, ``].join("\n");
  }
  if (isState(tier)) {
    const { pseudo, media } = STATE_SELECTORS[tier];
    // The pseudo-class before the gate: Blink tests a compound's simple selectors
    // in source order, the pseudo-class is a flag read, and the substring scans
    // the whole attribute (every [style*=] rule is tested on every styled element).
    const own = [
      `:where(${pseudo}[style*="--${tier}:"]) {`,
      ...inTier.map((utility) => `  --_${utility.name}-${tier}: var(--${utility.name}--${tier});`),
      `}`,
    ];
    const group = [
      `:where([data-ui~="group"]${pseudo} [style*="--group-"]) {`,
      ...inTier.map(
        (utility) => `  --_${utility.name}-g-${tier}: var(--group-${utility.name}--${tier});`,
      ),
      `}`,
    ];
    const body = [...own, ...group];
    return (media ? [`@media ${media} {`, ...indent(body, 2), `}`] : body).concat("").join("\n");
  }
  const body = [
    `:where([style*="--${tier}:"]) {`,
    ...inTier.map((utility) => `  --_${utility.name}-${tier}: var(--${utility.name}--${tier});`),
    `}`,
  ];
  return [`${breakpointQuery(tier as Breakpoint)} {`, ...indent(body, 2), `}`, ``].join("\n");
}

/**
 * The stuck state's setter (`_utilities-tier-stuck.css`). Every sticky element
 * (or one with `--stuck-state`) becomes a scroll-state container and publishes
 * the side it tracks as `--_stuck-side` (its `--stuck-state`, else the fallback
 * side); a layout's children keep their inline-size container beside it. A container condition cannot read `var()`, and a container query only
 * reaches descendants, so each side is one query, `scroll-state(stuck: <side>)
 * and style(--_stuck-side: <side>)`, both evaluated on the nearest scroll-state
 * container, switching on `--_stuck-on` for the `--<utility>--stuck` readers.
 * Where container scroll-state queries are unsupported, `base/scroll-state.ts`
 * writes the stuck sides to the container's `data-ui-stuck`; the container
 * then publishes the inherited `--_stuck-polyfill` (empty when stuck to its
 * side, guaranteed-invalid otherwise, reset on every container so a nested one
 * does not inherit its parent's) and the readers copy it. One rule then copies
 * every utility behind the switch (`var(--_stuck-on) var(--bg--stuck)`):
 * registered, not inheriting, and guaranteed-invalid by default, so with it off
 * the layer variable is invalid and the chain falls through.
 *
 * No reader rule names the container: a `[style*=…]` in an ancestor compound
 * would make every inline style change invalidate every styled descendant.
 */
function stuckSetter(tier: string, inTier: readonly Utility[]): string {
  const { modifier, supports, polyfill, fallback, sticky, sides } = STUCK_STATE;
  const containers = `${sticky}, [style*="--${modifier}:"]`;
  const container = (side: string) =>
    side === fallback
      ? `:is([style*="--${modifier}: ${side}"], ${sticky}:not([style*="--${modifier}:"]))`
      : `[style*="--${modifier}: ${side}"]`;
  const reader = `[style*="--${tier}:"]`;
  const lines = [
    `@supports ${supports} {`,
    `  :where(${containers}) {`,
    `    container-type: scroll-state;`,
    `    --_stuck-side: var(--${modifier}, ${fallback});`,
    `  }`,
    `  :where(ui-layout > *, [data-ui~="layout"] > *):where(${containers}) {`,
    `    container-type: inline-size scroll-state;`,
    `  }`,
  ];
  for (const side of sides) {
    lines.push(
      `  @container scroll-state(stuck: ${side}) and style(--_stuck-side: ${side}) {`,
      `    :where(${reader}) {`,
      `      --_stuck-on: ;`,
      `    }`,
      `  }`,
    );
  }
  lines.push(
    `}`,
    `@supports not ${supports} {`,
    `  :where(${containers}) {`,
    `    --_stuck-polyfill: initial;`,
    `  }`,
  );
  for (const side of sides) {
    lines.push(
      `  :where(${container(side)}[${polyfill}~="${side}"]) {`,
      `    --_stuck-polyfill: ;`,
      `  }`,
    );
  }
  lines.push(
    `  :where(${reader}) {`,
    `    --_stuck-on: var(--_stuck-polyfill);`,
    `  }`,
    `}`,
    `:where(${reader}) {`,
    ...inTier.map(
      (utility) =>
        `  --_${utility.name}-${tier}: var(--_stuck-on) var(--${utility.name}--${tier});`,
    ),
    `}`,
    ``,
  );
  return lines.join("\n");
}

/**
 * The effects composite: ring and shadow share one `box-shadow`,
 * behind the `--_focus-shadow` a primitive publishes on `:focus-visible`. Every
 * chain in it already ends in a literal, so the composite is also the
 * no-base rule for these utilities: a second copy gated on any tier, in
 * `@layer defaults` (see {@link noBaseRule}). The ring draws as an outset pair
 * and an inset pair weighted by the sign of `--_ring-w` (a zero-spread shadow
 * paints nothing), so `--ring: -2` is inset and a tier can flip it.
 */
export function compositeRule(
  utilities: readonly Utility[],
  defaults?: { skips: readonly string[] },
): string {
  const names = new Set(utilities.map((utility) => utility.name));
  const RING = BOX_SHADOW_COMPOSITE;
  if (!RING.some((name) => names.has(name))) return "";
  const gate = (prefix: string, suffix: string) =>
    `:is(${RING.map((name) => `[style*="--${prefix}${name}${suffix}"]`).join(", ")})`;
  const offset = "abs(var(--_ring-offset-w, 0px))";
  const band = `(${offset} + abs(var(--_ring-w, 0px)))`;
  const inset = "max(0, -1 * sign(var(--_ring-w, 0px)))";
  const offsetColor = "var(--_ring-offset-color-resolved, transparent)";
  const color = "var(--_ring-color-resolved, var(--color-ring))";
  const emission = `  box-shadow: var(--_focus-shadow, 0 0 #0000), 0 0 0 calc(${offset} * (1 - ${inset})) ${offsetColor}, 0 0 0 calc(${band} * (1 - ${inset})) ${color}, inset 0 0 0 calc(${offset} * ${inset}) ${offsetColor}, inset 0 0 0 calc(${band} * ${inset}) ${color}, var(--_shadow-resolved, 0 0 #0000);`;
  // with a base, in the utilities layer; on a tier alone, in the defaults layer
  // (see noBaseRule), where a primitive's own box-shadow wins
  const not = defaults?.skips.length ? `:not(${defaults.skips.join(", ")})` : "";
  return (
    defaults
      ? [`:where(:is(${gate("", "--")}, ${gate("group-", "--")})${not}) {`, emission, `}`, ``]
      : [`:where(${gate("", ":")}) {`, emission, `}`, ``]
  ).join("\n");
}

/**
 * Gradients: each `--bg-<type>` composes `background-image` from its prelude and
 * the shared `--bg-stops`. One rule per type, gated on the type's base; with
 * several types on one element the last in source (conic) wins.
 */
export function gradientRules(): string {
  return (
    GRADIENT_TYPES.map((type) =>
      [
        `:where([style*="--bg-${type}:"]) {`,
        `  background-image: ${type}-gradient(var(--_bg-${type}-resolved), var(--_bg-stops-resolved));`,
        `}`,
      ].join("\n"),
    ).join("\n") + "\n"
  );
}

/**
 * `--bg: none` clears the background: the color falls out on its own (`none`
 * is not a color, so the `--bg` emission is invalid and resolves to
 * transparent, in a primitive too), and these rules drop background-image at the
 * base and at each state tier. After the gradient rules, so `none` wins; lowest
 * precedence first (group states, then own states), as in the resolver chain.
 */
export function bgNoneRules(): string {
  const out = [`:where([style*="--bg: none"]) {`, `  background-image: none;`, `}`];
  // breakpoints ascend, then states (a state beats a breakpoint)
  for (const bp of BREAKPOINTS) {
    out.push(
      `${breakpointQuery(bp)} {`,
      `  :where([style*="--bg--${bp}: none"]) {`,
      `    background-image: none;`,
      `  }`,
      `}`,
    );
  }
  // the scroll state has no pseudo-class to gate on; its color still falls out
  const ascending = [...STATES].reverse().filter(hasGroup);
  const rule = (selector: string) => [`:where(${selector}) {`, `  background-image: none;`, `}`];
  for (const [group, states] of [
    [true, ascending],
    [false, ascending],
  ] as const) {
    for (const tier of states) {
      const { pseudo, media } = STATE_SELECTORS[tier];
      const body = group
        ? rule(`[data-ui~="group"]${pseudo} [style*="--group-bg--${tier}: none"]`)
        : rule(`${pseudo}[style*="--bg--${tier}: none"]`);
      out.push(...(media ? [`@media ${media} {`, ...body.map((l) => `  ${l}`), `}`] : body));
    }
  }
  return out.join("\n") + "\n";
}

/**
 * A pseudo-element rule: exact gate on `--<side>-<utility>`, read
 * straight from the (unregistered, inherited) utility on the pseudo-element.
 */
export function pseudoRule(utility: Utility, side: PseudoSide): string {
  if (!utility.pseudo || utility.emit === "none") return "";
  const n = `${side}-${utility.name}`;
  const lines = [`:where([style*="--${n}:"])::${side} {`];
  if (utility.mode === "dual") {
    lines.push(`  --_${n}-len: var(--${n});`, `  --_${n}-num: var(--${n});`);
    for (const property of utility.properties) {
      lines.push(`  ${property}: calc(var(--_${n}-len) + var(--_${n}-num) * var(--spacing));`);
    }
  } else {
    const value =
      utility.emit === "bg"
        ? `oklch(from var(--${n}) l c h / calc(alpha * var(--${side}-bg-alpha, 1)))`
        : `var(--${n})`;
    for (const property of utility.properties) lines.push(`  ${property}: ${value};`);
  }
  lines.push(`}`, ``);
  return lines.join("\n");
}

/** Typed pairs for dual utilities on pseudo-elements; declared on the pseudo-element itself. */
function pseudoRegistrations(utility: Utility): string {
  if (!utility.pseudo || utility.mode !== "dual") return "";
  return PSEUDO_SIDES.map(
    (side) =>
      register(`_${side}-${utility.name}-len`, '"<length-percentage>"', "0px") +
      register(`_${side}-${utility.name}-num`, '"<number>"', "0"),
  ).join("");
}

/**
 * `_breakpoints.css`: the layout width tokens (the bands and the component
 * sizes that follow them, in rem). The breakpoint tiers query the nearest
 * inline-size container at the same widths (`_utilities-tier-<breakpoint>.css`).
 * Comments in every generated file stay to a few words: `src/index.css` ships
 * them raw to zero-build pages, and the explanations live here.
 */
function breakpointsFile(): string {
  return [
    BANNER,
    "/* Layout widths (rem) */",
    "@layer variables {",
    "  :root {",
    ...BREAKPOINTS.map((bp) => `    --layout-${bp}: ${BREAKPOINT_REM[bp]}rem;`),
    "  }",
    "}",
    "",
  ].join("\n");
}

function familyFile(family: Family, utilities: readonly Utility[]): string {
  const rules = utilities
    .map(
      (utility) =>
        baseRule(utility, tiersOf(utility)) +
        shorthandTierRule(utility) +
        keywordRules(utility, tiersOf(utility)) +
        aliasRules(utility, tiersOf(utility)) +
        (utility.name === "display" ? displayShorthandRules() : ""),
    )
    .concat(compositeRule(utilities))
    .concat(utilities.some((utility) => utility.emit === "border") ? [borderSideRules()] : [])
    .concat(
      utilities.some((utility) => utility.name === "bg-stops")
        ? [gradientRules(), bgNoneRules()]
        : [],
    )
    .join("\n")
    .replace(/^(?=.)/gm, "  ");
  return `${BANNER}\n/* ${family} family */\n@layer ui.utilities {\n${rules}}\n`;
}

/**
 * `_defaults.css`: every tier-only rule (the no-base rules, their keyword tier
 * rules, the composite's tier copy) in `@layer defaults`, each skipping the
 * reset-layer elements that style its property on purpose.
 */
function defaultsFile(
  utilities: readonly Utility[],
  skips: Record<string, readonly string[]>,
): string {
  const RING = BOX_SHADOW_COMPOSITE;
  const rules = utilities
    .map(
      (utility) =>
        noBaseRule(utility, skips[utility.name]) +
        keywordRules(utility, tiersOf(utility), { skips: skips[utility.name] ?? [] }),
    )
    .concat(compositeRule(utilities, { skips: [...new Set(RING.flatMap((n) => skips[n] ?? []))] }))
    .join("\n")
    .replace(/^(?=.)/gm, "  ");
  return `${BANNER}\n/* Tier-only rules: below every component, vendor, and legacy layer */\n@layer defaults {\n${rules}}\n`;
}

/** Splits `text` at any of `separators` outside parentheses, brackets, and quotes. */
function splitOutside(text: string, separators: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let quote = "";
  let start = 0;
  for (let i = 0; i < text.length; i++) {
    const char = text[i]!;
    if (quote) {
      if (char === quote) quote = "";
    } else if (char === '"' || char === "'") quote = char;
    else if (char === "(" || char === "[") depth++;
    else if (char === ")" || char === "]") depth--;
    else if (depth === 0 && separators.includes(char)) {
      parts.push(text.slice(start, i));
      start = i + 1;
    }
  }
  parts.push(text.slice(start));
  return parts.map((part) => part.trim()).filter(Boolean);
}

/**
 * Each style rule's selectors and its declarations. A nested selector is
 * resolved against each parent selector: `&` stands for the parent, and one
 * without `&` is its descendant. At-rules (`@layer`, `@media`, `@supports`,
 * `@container`, `@starting-style`) pass their parent's selectors through;
 * keyframes have none. `layer` is the rule's cascade layer (`ui.components`),
 * or `""` outside any.
 */
export function styleRules(
  css: string,
): { selectors: string[]; declarations: string; layer: string }[] {
  const text = css.replace(/\/\*[\s\S]*?\*\//g, "");
  type Frame = { selectors: string[]; declarations: string; layer: string; keyframes?: true };
  const rules: Frame[] = [];
  const stack: Frame[] = [];
  let buffer = "";
  let quote = "";
  for (const char of text) {
    if (quote) {
      buffer += char;
      if (char === quote) quote = "";
    } else if (char === '"' || char === "'") {
      buffer += char;
      quote = char;
    } else if (char === "{") {
      const prelude = buffer.trim();
      buffer = "";
      const parent = stack.at(-1)?.selectors ?? [];
      const outer = stack.at(-1)?.layer ?? "";
      const named = /^@layer\s+([\w.-]+)$/.exec(prelude)?.[1];
      const layer = named ? (outer ? `${outer}.${named}` : named) : outer;
      // a keyframe's `from` / `50%` is not a selector
      if (prelude.startsWith("@keyframes") || stack.at(-1)?.keyframes) {
        stack.push({ selectors: [], declarations: "", layer, keyframes: true });
        continue;
      }
      const selectors = prelude.startsWith("@")
        ? parent
        : splitOutside(prelude, ",").flatMap((selector) =>
            !parent.length
              ? [selector]
              : selector.includes("&")
                ? parent.map((outer) => selector.replaceAll("&", outer))
                : parent.map((outer) => `${outer} ${selector}`),
          );
      stack.push({ selectors, declarations: "", layer });
    } else if (char === ";" || char === "}") {
      const frame = stack.at(-1);
      if (frame) frame.declarations += `${buffer};`;
      buffer = "";
      if (char === "}" && stack.length) rules.push(stack.pop()!);
    } else buffer += char;
  }
  return rules;
}

/** Pseudo-elements in their legacy one-colon form. */
const LEGACY_PSEUDO_ELEMENTS = new Set(["before", "after", "first-line", "first-letter"]);

/**
 * A compound's parts: type, universal, attribute, class, id, and pseudo-class
 * (with its argument). `null` when it has a pseudo-element.
 */
function compoundParts(compound: string): string[] | null {
  const parts: string[] = [];
  let i = 0;
  while (i < compound.length) {
    const rest = compound.slice(i);
    if (rest.startsWith("::")) return null;
    let part = /^(?:\[[^\]]*\]|[.#][\w-]+|\*|[a-zA-Z][\w-]*|:[a-z-]+)/.exec(rest)?.[0];
    if (!part) throw new Error(`unparsed selector: ${compound}`);
    if (part.startsWith(":") && LEGACY_PSEUDO_ELEMENTS.has(part.slice(1))) return null;
    if (part.startsWith(":") && rest[part.length] === "(") {
      let depth = 0;
      let end = part.length;
      do {
        if (rest[end] === "(") depth++;
        else if (rest[end] === ")") depth--;
        end++;
      } while (depth && end < rest.length);
      part = rest.slice(0, end);
    }
    parts.push(part);
    i += part.length;
  }
  return parts;
}

/**
 * A compound without its state and structural pseudo-classes, the type first.
 * `:not()` and `:has()` stay, since they narrow what the rule styles (a switch
 * styles the label that `:has()` its input, not every label), with their own
 * states removed; a `:not()` left empty is dropped. `:root` is `html`. `null`
 * when the compound has a pseudo-element.
 */
function restCompound(compound: string): string | null {
  const parts = compoundParts(compound);
  if (!parts) return null;
  const kept: string[] = [];
  for (const part of parts) {
    if (part === ":root") kept.push("html");
    else if (part.startsWith(":where(") || part.startsWith(":is(")) {
      // a group stays one selector (`:is(ui-layout, [data-ui~="layout"])`), and one
      // plain compound joins this one (`:where(kbd)` is `kbd`)
      const items = splitOutside(part.slice(part.indexOf("(") + 1, -1), ",").map((item) =>
        restComplex(item),
      );
      const inner = items.filter((item): item is string => item !== null);
      if (!inner.length) return null;
      if (inner.includes("*")) continue;
      if (inner.length === 1 && splitOutside(inner[0]!, " >+~").length === 1)
        kept.push(...compoundParts(inner[0]!)!);
      else kept.push(`:is(${inner.join(", ")})`);
    } else if (part.startsWith(":not(") || part.startsWith(":has(")) {
      const relative = part.startsWith(":has(");
      const inner = splitOutside(part.slice(5, -1), ",")
        .map((item) => restComplex(item, relative))
        .filter((item): item is string => item !== null && item !== "*");
      if (inner.length) kept.push(`${part.slice(0, 5)}${inner.join(", ")})`);
    } else if (!part.startsWith(":")) kept.push(part);
  }
  const type = kept.find((part) => /^[a-zA-Z]/.test(part)) ?? "";
  const rest = kept.filter((part) => part !== type && part !== "*").join("");
  return type + rest || "*";
}

/** A complex selector as {@link restCompound}s; a `:has()` argument may lead with `>`. */
function restComplex(selector: string, relative = false): string | null {
  const tokens = splitOutside(selector.replace(/\s*([>+~])\s*(?!=)/g, " $1 "), " ");
  const out: string[] = [];
  for (const [i, token] of tokens.entries()) {
    if (token === ">" || token === "+" || token === "~") {
      if (i === 0 && !relative) return null;
      out.push(token);
      continue;
    }
    const compound = restCompound(token);
    if (compound === null) return null;
    out.push(compound);
  }
  return out.join(" ");
}

/**
 * A rule selector as the elements it can style at rest or in any state, as
 * {@link restCompound}s (`:where()` becomes `:is()`). Dropping a state widens
 * the match, which errs toward keeping a primitive's own value. A selector with
 * a pseudo-element styles no element itself, so it yields none.
 */
export function restSelectors(selector: string): string[] {
  const rest = restComplex(selector.replace(/\s+/g, " ").trim());
  return rest === null ? [] : [rest];
}

/**
 * Longhands each shorthand sets, for the properties the utilities emit: a
 * primitive's `padding` sets what `--px` emits, but its `flex` does not set
 * `--flex-wrap`'s property.
 */
const LONGHANDS: Readonly<Record<string, readonly string[]>> = {
  padding: [
    "padding-inline",
    "padding-block",
    "padding-inline-start",
    "padding-inline-end",
    "padding-block-start",
    "padding-block-end",
    "padding-top",
    "padding-right",
    "padding-bottom",
    "padding-left",
  ],
  "padding-inline": ["padding-inline-start", "padding-inline-end", "padding-left", "padding-right"],
  "padding-block": ["padding-block-start", "padding-block-end", "padding-top", "padding-bottom"],
  background: ["background-color", "background-image"],
  flex: ["flex-grow", "flex-shrink", "flex-basis"],
  "flex-flow": ["flex-direction", "flex-wrap"],
  gap: ["row-gap", "column-gap"],
  "grid-column": ["grid-column-start", "grid-column-end"],
  "grid-row": ["grid-row-start", "grid-row-end"],
  "grid-area": ["grid-row-start", "grid-column-start", "grid-row-end", "grid-column-end"],
  "grid-template": ["grid-template-columns", "grid-template-rows"],
  grid: [
    "grid-template-columns",
    "grid-template-rows",
    "grid-auto-flow",
    "grid-auto-columns",
    "grid-auto-rows",
  ],
  "place-items": ["align-items", "justify-items"],
  "place-content": ["align-content", "justify-content"],
  "place-self": ["align-self", "justify-self"],
  overflow: ["overflow-x", "overflow-y"],
  "text-decoration": ["text-decoration-line"],
  "text-wrap": ["text-wrap-mode", "text-wrap-style"],
  "border-radius": [
    "border-start-start-radius",
    "border-start-end-radius",
    "border-end-start-radius",
    "border-end-end-radius",
    "border-top-left-radius",
    "border-top-right-radius",
    "border-bottom-left-radius",
    "border-bottom-right-radius",
  ],
};

/** True when declaring `declared` sets some of `emitted` (one is the other, or its shorthand). */
function overlaps(declared: string, emitted: string): boolean {
  return (
    declared === emitted ||
    !!LONGHANDS[declared]?.includes(emitted) ||
    !!LONGHANDS[emitted]?.includes(declared)
  );
}

/** The properties a utility's no-base rule sets: its own, or `box-shadow` for the composite. */
function emittedProperties(utility: Utility): readonly string[] {
  if (utility.properties.length) return utility.properties;
  return (BOX_SHADOW_COMPOSITE as readonly string[]).includes(utility.name) ? ["box-shadow"] : [];
}

/** A state pseudo-class: a rule that needs one applies only while the element is in that state. */
const STATE_PSEUDO =
  /:(?:hover|active|focus|focus-visible|focus-within|checked|indeterminate|disabled|open|popover-open|modal|user-invalid|target)(?![\w-])/;

/**
 * True when the rule's selector can match an element at rest: it needs no state
 * pseudo-class outside a `:not()` (`button:not(:disabled)` matches at rest;
 * `button:disabled` does not).
 */
export function appliesAtRest(selector: string): boolean {
  return !STATE_PSEUDO.test(selector.replace(/:not\((?:[^()]|\([^()]*\))*\)/g, ""));
}

/** The cascade layers below `@layer defaults`: their rules lose to the tier-only rules. */
const BELOW_DEFAULTS = new Set(["variables", "reset"]);

/** The tier-only properties that inherit: `inherit` there keeps a parent's value the literal would replace. */
const INHERITED = new Set(["text-align", "text-wrap", "text-wrap-mode", "text-wrap-style"]);

/**
 * True when a reset declaration only normalizes the element, which the
 * tier-only rule may beat: its value is the utility's own literal (`padding: 0`),
 * `initial`, or `inherit` / `unset` on a property that does not inherit (a
 * link's `text-decoration: inherit`). `flex-shrink: 0` on `hr` styles it (the
 * literal is `1`), and so does `text-align: inherit` on a button.
 */
function normalizes(utility: Utility, property: string, value: string): boolean {
  // an integer utility's literal is its own input (`1` column), not a CSS value
  const literal = utility.mode === "integer" ? undefined : (utility.noBase ?? "none");
  const zero = /^(?:0(?:px|r?em|%)?\s*)+$/.test(value) ? "0" : value;
  if (zero === literal || value === "initial") return true;
  return (value === "inherit" || value === "unset") && !INHERITED.has(property);
}

/**
 * Elements the browser's own stylesheet styles on purpose, which sits below
 * `@layer defaults` too: a modal dialog is `position: fixed` there.
 */
const USER_AGENT_STYLED: Readonly<Record<string, readonly string[]>> = {
  position: ["dialog", "[popover]"],
};

/** The utilities a tier-only rule exists for: the no-base ones, and the box-shadow composite's. */
function tierOnly(utility: Utility): boolean {
  return utility.noBase !== undefined || emittedProperties(utility)[0] === "box-shadow";
}

/**
 * What the kit's own stylesheets (the primitives and the hand-written base)
 * do with each utility, as {@link restSelectors}:
 *
 * - `reads`: the elements a rule reads `--_<utility>-resolved` on. A tier alone
 *   works there: the resolver is gated on the tier, and the rule's chain falls
 *   back to its own value at rest.
 * - `blocks`: for a tier-only utility, the elements a rule above `defaults`
 *   sets its property on at rest (or one it overlaps), plus the `skips`. That
 *   rule beats the tier-only rule, so the element keeps its value at rest, and a
 *   tier alone applies only where the element is also in `reads`.
 * - `skips`: the part of `blocks` in a layer below `defaults` (the reset),
 *   which `@layer defaults` would beat and so must skip by selector (inline
 *   code's padding, `sub`'s `position: relative`). A reset rule that only
 *   normalizes ({@link normalizes}: `* { padding: 0 }`) is not one: the
 *   tier-only rules are there to beat it. The browser's own styling
 *   ({@link USER_AGENT_STYLED}) is skipped too. Each is cut to its subject where
 *   the subject has an attribute of its own.
 */
export function kitStyling(
  src = join(dirname(fileURLToPath(import.meta.url)), "..", "src"),
  utilities: readonly Utility[] = UTILITIES,
): {
  reads: Record<string, string[]>;
  blocks: Record<string, string[]>;
  skips: Record<string, string[]>;
} {
  const names = new Set(utilities.map((utility) => utility.name));
  const maps = { reads: new Map<string, Set<string>>(), blocks: new Map(), skips: new Map() };
  const add = (map: Map<string, Set<string>>, name: string, selectors: readonly string[]) => {
    const set = map.get(name) ?? new Set<string>();
    for (const selector of selectors) set.add(selector);
    map.set(name, set);
  };
  // a subject with an attribute of its own (a slot, an input type; not one inside
  // `:not()` or `:has()`) names the element alone, which keeps the CSS lists short
  const short = (selector: string) => {
    const subject = splitOutside(selector, " >+~").at(-1) ?? selector;
    const own = subject.replace(/:(?:not|has)\((?:[^()]|\([^()]*\))*\)/g, "");
    return own.includes("[") ? subject : selector;
  };
  const generated = /^_(?:layers|breakpoints|properties|utilities-|defaults)/;
  const files = [
    ...readdirSync(join(src, "primitives"))
      .sort()
      .flatMap((name) =>
        readdirSync(join(src, "primitives", name))
          .filter((file) => file.endsWith(".css"))
          .sort()
          .map((file) => join(src, "primitives", name, file)),
      ),
    ...readdirSync(join(src, "base"))
      .filter((file) => file.endsWith(".css") && !generated.test(file))
      .sort()
      .map((file) => join(src, "base", file)),
  ];
  for (const file of files) {
    for (const rule of styleRules(readFileSync(file, "utf8"))) {
      const selectors = rule.selectors.flatMap(restSelectors);
      if (!selectors.length) continue;
      for (const m of rule.declarations.matchAll(/--_([a-z0-9-]+)-resolved\b/g)) {
        if (names.has(m[1]!)) add(maps.reads, m[1]!, selectors);
      }
      const declared = [...rule.declarations.matchAll(/(?:^|;)\s*([a-z][a-z-]*)\s*:([^;]*)/g)].map(
        (m) => ({ property: m[1]!, value: m[2]!.trim().toLowerCase() }),
      );
      // a rule that applies only in a state (a disabled button's opacity) does not
      // set the property at rest, so a tier alone still applies there
      const atRest = rule.selectors.filter(appliesAtRest);
      const below = BELOW_DEFAULTS.has(rule.layer.split(".")[0]!);
      for (const utility of utilities.filter(tierOnly)) {
        const emitted = emittedProperties(utility);
        const sets = declared.filter((d) => emitted.some((e) => overlaps(d.property, e)));
        if (!sets.length) continue;
        if (!below) add(maps.blocks, utility.name, atRest.flatMap(restSelectors));
        else if (sets.some((d) => !normalizes(utility, d.property, d.value))) {
          add(maps.blocks, utility.name, selectors);
          add(maps.skips, utility.name, selectors.map(short));
        }
      }
    }
  }
  const sorted = (map: Map<string, Set<string>>) =>
    Object.fromEntries(
      [...map]
        .filter(([, set]) => set.size)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([name, set]) => [name, [...set].sort()]),
    );
  for (const [name, selectors] of Object.entries(USER_AGENT_STYLED)) {
    add(maps.blocks, name, selectors);
    add(maps.skips, name, selectors);
  }
  return { reads: sorted(maps.reads), blocks: sorted(maps.blocks), skips: sorted(maps.skips) };
}

/** A string literal in the formatter's quote style. */
function literal(text: string): string {
  return text.includes('"') ? `'${text}'` : `"${text}"`;
}

/** An object key as the formatter writes it: bare when it is an identifier. */
function key(text: string): string {
  return /^[A-Za-z_$][\w$]*$/.test(text) ? text : literal(text);
}

/**
 * The styling facts with each selector stored once: `selectors` lists them, and
 * `reads` / `blocks` refer to them by index (most rules set several utilities,
 * so each selector repeats across many entries).
 */
export function indexStyling(styling: {
  reads: Record<string, string[]>;
  blocks: Record<string, string[]>;
}): {
  selectors: string[];
  reads: Record<string, number[]>;
  blocks: Record<string, number[]>;
} {
  const selectors = [
    ...new Set([...Object.values(styling.reads), ...Object.values(styling.blocks)].flat()),
  ].sort();
  const index = new Map(selectors.map((selector, i) => [selector, i]));
  const refer = (record: Record<string, string[]>) =>
    Object.fromEntries(
      Object.entries(record).map(([name, list]) => [name, list.map((s) => index.get(s)!)]),
    );
  return { selectors, reads: refer(styling.reads), blocks: refer(styling.blocks) };
}

/** A generated `Record<string, readonly number[]>` literal's entries, wrapped like the formatter. */
function recordEntries(record: Record<string, readonly number[]>): string {
  return Object.entries(record)
    .map(([name, indices]) => {
      const line = `  ${key(name)}: [${indices.join(", ")}],`;
      if (line.length <= 100) return `${line}\n`;
      // the formatter fills each line up to the width
      const lines: string[] = [];
      let current = "   ";
      for (const index of indices) {
        const next = ` ${index},`;
        if (current.length + next.length > 100) {
          lines.push(current);
          current = "   ";
        }
        current += next;
      }
      lines.push(current);
      return `  ${key(name)}: [\n${lines.join("\n")}\n  ],\n`;
    })
    .join("");
}

/**
 * `kit-styling.ts`: where the kit reads each utility and where it sets the
 * property itself, so the audit asks for a base exactly where a tier alone does
 * nothing.
 */
function kitStylingModule(styling: ReturnType<typeof kitStyling>): string {
  const { selectors, reads, blocks } = indexStyling(styling);
  return `// Generated by scripts/generate-utilities.ts from the kit's stylesheets — do not edit.

/** Every selector below, once (rule selectors without state pseudo-classes); the records index it. */
export const KIT_SELECTORS: readonly string[] = [
${selectors.map((selector) => `  ${literal(selector)},\n`).join("")}];

/** For each utility, the elements the kit reads it on through its own chain: a tier alone works there. */
export const TIER_READS: Readonly<Record<string, readonly number[]>> = {
${recordEntries(reads)}};

/**
 * For each tier-only utility (a no-base one, or the box-shadow composite's),
 * the elements the kit sets its property on above \`@layer defaults\`: they keep
 * their own value, and a tier alone applies there only through \`TIER_READS\`.
 */
export const TIER_BLOCKS: Readonly<Record<string, readonly number[]>> = {
${recordEntries(blocks)}};
`;
}

/** Every generated file, keyed by its name under `src/base/`. */
export function generate(
  utilities: readonly Utility[] = UTILITIES,
  styling: ReturnType<typeof kitStyling> = kitStyling(),
): Map<string, string> {
  const files = new Map<string, string>();
  files.set("_breakpoints.css", breakpointsFile());
  files.set("_defaults.css", defaultsFile(utilities, styling.skips));
  files.set("kit-styling.ts", kitStylingModule(styling));
  // The stuck state's privates (see stuckSetter): the switch the readers copy,
  // the side a container tracks (typed, so the style() query compares idents and
  // a bad side falls back), the polyfill's inherited flag, and --stuck-state
  // itself, non-inheriting like every utility so a nested container reads its own.
  const stuckRegistrations =
    register("_stuck-on") +
    register("_stuck-side", `"${STUCK_STATE.sides.join(" | ")}"`, STUCK_STATE.fallback) +
    register("_stuck-polyfill", undefined, undefined, true) +
    register(STUCK_STATE.modifier);
  files.set(
    "_properties.css",
    `${BANNER}\n/* Registrations: utility, layer variable, resolver, dual pair */\n${utilities.map(registrations).join("")}\n/* Dual pairs on pseudo-elements */\n${utilities.map(pseudoRegistrations).join("")}\n/* Focus ring, published by primitives */\n${register("_focus-shadow")}\n/* Stuck state */\n${stuckRegistrations}\n/* --display shorthands' flex-direction channel */\n${["", ...BREAKPOINTS.map((bp) => `-${bp}`), "-resolved"].map((suffix) => register(`_flex-direction${suffix}`)).join("")}`,
  );
  for (const tier of [...BREAKPOINTS, ...STATES]) {
    const inTier = utilities.filter((utility) => tiersOf(utility).includes(tier));
    files.set(
      `_properties-${tier}.css`,
      `${BANNER}\n/* ${tier} tier registrations */\n${inTier.map((utility) => tierRegistrations(utility, tier)).join("")}`,
    );
  }
  for (const tier of [...BREAKPOINTS, ...STATES]) {
    files.set(
      `_utilities-tier-${tier}.css`,
      `${BANNER}\n/* ${tier} tier setter */\n@layer ui.utilities {\n${setterRule(tier, utilities).replace(/^(?=.)/gm, "  ")}}\n`,
    );
  }
  const families = [...new Set(utilities.map((utility) => utility.family))];
  for (const family of families) {
    files.set(
      `_utilities-${family}.css`,
      familyFile(
        family,
        utilities.filter((utility) => utility.family === family),
      ),
    );
  }
  const pseudo = [...utilities, ...PSEUDO_ONLY]
    .flatMap((utility) => PSEUDO_SIDES.map((side) => pseudoRule(utility, side)))
    .filter(Boolean)
    .join("\n")
    .replace(/^(?=.)/gm, "  ");
  files.set(
    "_utilities-pseudo.css",
    `${BANNER}\n/* Pseudo-element utilities (--before-, --after-) */\n@layer ui.utilities {\n${pseudo}}\n`,
  );
  return files;
}

export function main(): void {
  const base = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "base");
  for (const [file, text] of generate()) {
    writeFileSync(join(base, file), text);
    console.log(`wrote src/base/${file}`);
  }
}

if (import.meta.main) main();
